input.command:
cd ~/.claude-rekru/projects/-home-linux-boi-vehicle-handover-starter && for f in *.jsonl; do echo "== $f $(wc -c <$f) $(head -c 0 $f)"; python3 -I - "$f" <<'EOF'
import json,sys
n=0
for l in open(sys.argv[1]):
    try:d=json.loads(l)
    except: continue
    if d.get('type')=='user':
        m=d['message']['content']
        if isinstance(m,list): m=' '.join(x.get('text','') for x in m if isinstance(x,dict))
        if m.strip() and not m.startswith('<'):
            print(d.get('timestamp','')[:19], m[:300].replace('\n',' ')); n+=1
            if n>=4: break
EOF
done

